void Placement::placement_manager(int32_t deviceId,
                                  aclrtContext currentContext) {

    if (enable_new_context_) {
        ACLCHECK(aclrtSetDevice(deviceId));
        ACLCHECK(aclrtCreateContext(&createdContext_, deviceId));
